function assistantOrderRows(filters={}){
  return (state.orders||[]).filter(o=>{
    if(filters.activeOnly && o.stage==='completed')return false;
    if(filters.stage && o.stage!==filters.stage)return false;
    return true;
  }).map(o=>({orden:o.id,cliente:o.customer||'—',cantidad:Number(o.qty)||0,etapa:stageLabel(o.stage||'waiting_material'),entrega:o.deliveryDate||o.due||'—'}));
}
function assistantInventoryRows(filters={}){
  return (state.lumber||[]).filter(x=>{
    const available=availableOf(x);
    if(filters.lowOnly && available>=Number(x.min||0))return false;
    if(filters.query && !String(x.size||x.family||'').toLowerCase().includes(String(filters.query).toLowerCase()))return false;
    return true;
  }).map(x=>({material:x.size||x.family||x.id,origen:x.origin==='recycled'?'Reciclado':'Nuevo',existencia:Number(x.qty)||0,reservado:Number(x.reserved)||0,disponible:availableOf(x),mínimo:Number(x.min)||0}));
}
function createPalletOpsAssistantProvider(){
  return {
    async sendMessage({message,executeTool,signal}){
      const q=String(message||'').toLowerCase();
      if(signal?.aborted)throw new DOMException('Cancelado','AbortError');
      if(/inventario|madera|material/.test(q)){
        const lowOnly=/baj|mínim|falt|alert/.test(q),r=await executeTool('searchInventory',{lowOnly});
        return {type:'table',content:lowOnly?'Materiales bajo mínimo':'Inventario',data:r.data};
      }
      if(/producci|trabajador|empleado/.test(q)){
        const r=await executeTool('getProductionRecords',{});
        if(!r.data.length)return {type:'text',content:'Todavía no hay registros de producción capturados en el prototipo.'};
        return {type:'table',content:'Producción registrada',data:r.data};
      }
      if(/despacho|carga|listas? para/.test(q)){
        const r=await executeTool('getOrders',{stage:'ready_load'});
        return {type:'table',content:'Órdenes listas para carga/despacho',data:r.data};
      }
      if(/orden|pedido|atras|entrega/.test(q)){
        const r=await executeTool('getOrders',{activeOnly:true});
        return {type:'table',content:'Órdenes activas',data:r.data};
      }
      if(/cliente/.test(q)){
        const r=await executeTool('getCustomers',{});
        return {type:'table',content:'Clientes',data:r.data};
      }
      return {type:'text',content:'Puedo consultar órdenes, inventario, producción, clientes y órdenes listas para despacho. Esta V1 integrada es de solo lectura; los motores pesados permanecen inactivos hasta que una función los requiera.'};
    }, async destroy(){}
  };
}
async function ensureAIAssistantLoaded(){
  if(aiAssistantInstance&&document.getElementById('aiAssistantMount')){
    if(!aiAssistantUI){const ui=await import('./ai-assistant/assistant-ui.js');aiAssistantUI=new ui.AssistantUI({assistant:aiAssistantInstance,container:'#aiAssistantMount'});}
    return;
  }
  if(aiAssistantLoading)return aiAssistantLoading;
  aiAssistantLoading=(async()=>{
    if(!document.getElementById('po-ai-css')){const link=document.createElement('link');link.id='po-ai-css';link.rel='stylesheet';link.href='ai-assistant/assistant.css';document.head.appendChild(link);}
    const [{AIAssistant},{AssistantUI}]=await Promise.all([import('./ai-assistant/assistant-core.js'),import('./ai-assistant/assistant-ui.js')]);
    aiAssistantInstance=new AIAssistant({providerInstance:createPalletOpsAssistantProvider(),user:{id:'prototype-admin',permissions:['assistant:read']},timeoutMs:20000,toolTimeoutMs:8000});
    aiAssistantInstance.registerTool({name:'getOrders',description:'Consultar órdenes.',operation:'read',permission:'assistant:read',execute:async p=>assistantOrderRows(p)});
    aiAssistantInstance.registerTool({name:'searchInventory',description:'Consultar inventario bajo demanda.',operation:'read',permission:'assistant:read',execute:async p=>assistantInventoryRows(p)});
    aiAssistantInstance.registerTool({name:'getProductionRecords',description:'Consultar producción.',operation:'read',permission:'assistant:read',execute:async()=> (state.productionLog||[]).map(x=>({fecha:x.createdAt?new Date(x.createdAt).toLocaleString('es-US'):'—',trabajador:workerName(x.workerId),orden:x.orderId||'—',operación:x.type||x.operation||'Producción',cantidad:Number(x.qty||x.quantity)||0}))});
    aiAssistantInstance.registerTool({name:'getCustomers',description:'Consultar clientes.',operation:'read',permission:'assistant:read',execute:async()=> (state.customers||[]).map(c=>({cliente:c.name,qc:c.qcDefault?'Sí':'No',ht:c.htDefault?'Sí':'No',retorno:trailerReturnLabel(c.trailerReturn)}))});
    aiAssistantUI=new AssistantUI({assistant:aiAssistantInstance,container:'#aiAssistantMount'});updateAIAuditSummary();
  })().catch(err=>{console.error('No se pudo cargar Asistente IA',err);const mount=document.getElementById('aiAssistantMount');if(mount)mount.innerHTML=`<div class="notification warn"><b>No se pudo cargar el Asistente IA.</b><div class="small">${String(err.message||err)}</div></div>`;}).finally(()=>{aiAssistantLoading=null});
  return aiAssistantLoading;
}
function updateAIAuditSummary(){
  const target=document.getElementById('aiAuditSummary');if(!target||!aiAssistantInstance)return;
  const entries=aiAssistantInstance.getAuditEntries().slice(-8).reverse();
  target.innerHTML=entries.length?`<div class="table-wrap"><table><thead><tr><th>Hora</th><th>Herramienta</th><th>Operación</th><th>Resultado</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.timestamp).toLocaleTimeString('es-US')}</td><td><b>${e.tool||'—'}</b></td><td>${e.operation||'read'}</td><td>${e.success?(e.resultSummary||'OK'):`Error: ${e.error||'—'}`}</td></tr>`).join('')}</tbody></table></div>`:'Sin consultas todavía.';
}

function render(){
  try{
    if(!views[currentView])currentView='inicio';
    const [t,s]=views[currentView];el.title.textContent=t;el.subtitle.textContent=s;
    const renderer=({inicio:renderInicio,ordenes:renderOrdenes,madera:renderMadera,conversion:renderConversion,produccion:renderProduccion,fabricacion:renderFabricacion,terminados:renderTerminados,carga:renderCarga,reportes:renderReportes,asistente:renderAsistente,resumen:renderResumen,trailers:renderTrailers,desarme:renderDesarme,historial:renderHistorial,configuracion:renderConfiguracion})[currentView];
    el.content.innerHTML=renderer?renderer():renderInicio();bindDynamic();applyTheme();if(currentView==='asistente')ensureAIAssistantLoaded();
  }catch(err){
    console.error('Error al dibujar la vista',currentView,err);
    el.content.innerHTML=`<div class="card"><h2>No se pudo cargar esta vista</h2><p class="small">Se detectó un dato antiguo o incompatible. La aplicación sigue disponible.</p><button class="btn" id="recoverView">Volver al inicio</button></div>`;
    document.getElementById('recoverView')?.addEventListener('click',()=>{currentView='inicio';location.hash='inicio';render()});applyTheme();
  }
}
function renderMadera(){
  const raw=state.lumber.filter(x=>x.category==='raw'),finished=state.lumber.filter(x=>x.category==='finished'),ranges=state.lumber.filter(x=>x.category==='range');
  const rows=list=>list.map(x=>{const a=availableOf(x),origin=x.origin==='recycled'?'recycled':'new';return `<tr><td><b>${x.size}</b><div class="small">${x.family}${x.way?` · ${String(x.way).toUpperCase()}`:''} · ${origin==='recycled'?'Reciclado':'Nuevo'}</div></td><td><b>${origin==='recycled'?'Reciclado':`#${x.grade}`}</b></td><td>${x.qty}</td><td>${x.reserved||0}</td><td>${a}</td><td>${x.min||0}</td><td>${a<(x.min||0)?pill('Bajo','yellow'):pill('Bien','green')}</td></tr>`}).join('');
  const sheets=(state.sheetMaterials||[]).map(x=>`<tr><td><b>${sheetLabel(x)}</b><div class="small">${x.kind||'Plywood'}${x.grade?` · ${x.grade}`:''}</div></td><td>${x.qty||0}</td><td>${x.min||0}</td><td>${money(x.unitCost||0)}</td><td>${Number(x.qty||0)<Number(x.min||0)?pill('Bajo','yellow'):pill('Bien','green')}</td></tr>`).join('');
  return `<div class="toolbar"><button class="btn" data-action="receiveWood">+ Recibir madera</button><button class="btn secondary" data-action="addMaterial">+ Agregar tipo de madera</button><button class="btn secondary" data-action="addSheetMaterial">+ Agregar plywood / panel</button><button class="btn secondary" data-go="conversion">Conversión manual</button></div><div class="section-head"><div><h2>Materia prima</h2><p>2×4, 2×6, 4×4, 4×6 y cualquier medida que agregues al catálogo.</p></div></div><div class="table-wrap"><table><thead><tr><th>Medida</th><th>Calidad</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(raw)}</tbody></table></div><div class="section-head section"><div><h2>Piezas ya cortadas</h2><p>El planificador usa estas piezas primero antes de cortar madera larga.</p></div></div><div class="table-wrap"><table><thead><tr><th>Pieza lista</th><th>Calidad</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(finished)||'<tr><td colspan="7">Sin piezas listas.</td></tr>'}</tbody></table></div><div class="section-head section"><div><h2>Reciclado sin medida final</h2><p>Tablas y runners recuperados por rango. Si no se conoce el largo exacto, al procesarlos no se calcula desperdicio.</p></div></div><div class="table-wrap"><table><thead><tr><th>Rango</th><th>Origen</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(ranges)||'<tr><td colspan="7">Sin piezas recicladas por rango.</td></tr>'}</tbody></table></div><div class="section-head section"><div><h2>Plywood / paneles</h2><p>Inventario base para crates, tapas y pallets que usan panel. El optimizador global de paneles se conectará después.</p></div></div><div class="table-wrap"><table><thead><tr><th>Panel</th><th>Existencia</th><th>Mínimo</th><th>Costo unitario</th><th>Estado</th></tr></thead><tbody>${sheets||'<tr><td colspan="5">Todavía no hay plywood o paneles registrados.</td></tr>'}</tbody></table></div><div class="section notification info"><b>Regla:</b> material nuevo y reciclado se mantienen separados. El material reciclado por rango puede ser tabla o runner 2-Way / 4-Way y no genera merma automática mientras el largo real sea desconocido.</div>`
}
function wasteMonthKey(ts){const d=new Date(ts||Date.now());return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function wasteMonthLabel(key){const [y,m]=String(key).split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('es-US',{month:'long',year:'numeric'})}
function wasteMonthlyTotals(){const totals={};for(const w of state.wasteLog||[]){const k=w.month||wasteMonthKey(w.createdAt);totals[k]=(totals[k]||0)+(Number(w.wasteTotalIn)||0)}return Object.entries(totals).sort((a,b)=>b[0].localeCompare(a[0]))}
function cutRowsHtml(){return `<div id="convCutRows" class="conversion-cut-list"><div class="board-editor-head"><b>Patrón de cortes por cada pieza fuente</b><button type="button" class="btn ghost" data-add-cut>+ Agregar corte</button></div><div class="conversion-cut-row" data-cut-row><label><span>Largo (in)</span><input data-cut-length type="number" min="0.125" step="0.125" value="48"></label><label><span>Piezas de este largo</span><input data-cut-qty type="number" min="1" step="1" value="2"></label><button type="button" class="remove-board" data-remove-cut aria-label="Eliminar corte">×</button></div></div>`}
function wasteHistoryHtml(){const months=wasteMonthlyTotals(),recent=(state.wasteLog||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,30);return `<div class="section"><div class="section-head"><div><h2>Desperdicio mensual</h2><p>Se suma automáticamente solo a partir de los cortes de largo guardados.</p></div></div><div class="grid metrics">${months.length?months.slice(0,6).map(([k,v])=>metric(wasteMonthLabel(k),`${Number(v.toFixed(3))} in`,'Desperdicio acumulado')).join(''):metric('Este mes','0 in','Aún no hay desperdicio registrado')}</div></div><div class="section"><div class="section-head"><div><h2>Historial de desperdicio</h2><p>Cada corte conserva el sobrante por pieza y el total de la operación.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Material fuente</th><th>Cantidad</th><th>Patrón</th><th>Usado / pieza</th><th>Sobrante / pieza</th><th>Desperdicio total</th></tr></thead><tbody>${recent.map(w=>`<tr><td>${new Date(w.createdAt).toLocaleString('es-US')}</td><td><b>${w.sourceSize}</b></td><td>${w.sourceQty}</td><td>${(w.cuts||[]).map(c=>`${c.qty}×${c.lengthIn}&quot;`).join(' + ')}</td><td>${w.usedPerSourceIn} in</td><td>${w.wastePerSourceIn} in</td><td><b>${w.wasteTotalIn} in</b></td></tr>`).join('')||'<tr><td colspan="7">Todavía no hay cortes registrados.</td></tr>'}</tbody></table></div></div>`}
function renderConversion(){const sources=state.lumber.filter(x=>availableOf(x)>0&&parseFamilyDims(x.family));const families=[...new Set(state.lumber.map(x=>x.family).filter(f=>parseFamilyDims(f)))].sort((a,b)=>{const A=parseFamilyDims(a),B=parseFamilyDims(b);return (A[0]*A[1])-(B[0]*B[1])});return `<div class="grid metrics">${metric('Materiales disponibles',sources.length,'Materia prima y piezas ya cortadas')}${metric('Operaciones','2','Cortar largo o convertir sección')}${metric('Corte múltiple','Sí','Varios largos desde una misma pieza')}${metric('Desperdicio',`${Number(wasteMonthlyTotals()[0]?.[1]||0).toFixed(2)} in`,'Mes más reciente registrado')}</div><div class="section card"><h2 style="font-size:17px;margin-top:0">Conversión y corte de madera</h2><p class="small">En corte de largo puedes crear varios tamaños desde la misma pieza madre. El sistema suma los largos, muestra el sobrante y guarda ese desperdicio. En conversión de sección, tú sigues indicando manualmente el rendimiento final.</p><div class="form-grid"><label><span>Operación</span><select id="convOperation"><option value="length">Cortar largo</option><option value="section">Convertir sección</option></select></label><label><span>Madera fuente</span><select id="convSource">${sources.map(x=>`<option value="${x.id}">${x.size} · ${x.origin==='recycled'?'Reciclado':`#${x.grade}`} · disp. ${availableOf(x)}</option>`).join('')}</select></label><label><span>Cantidad de piezas fuente</span><input id="convQty" type="number" min="1" step="1" value="1"></label><label><span>Trabajador / responsable</span><select id="convWorker"><option value="">— Seleccionar trabajador —</option>${activeWorkers().map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select></label><div class="toolbar" style="align-items:end"><button type="button" class="btn secondary" data-action="addWorker">+ Agregar trabajador</button></div><label id="convYieldWrap" style="display:none"><span>Piezas destino por cada fuente</span><input id="convYield" type="number" min="1" step="1" value="2"></label></div><div id="convLengthFields">${cutRowsHtml()}<div class="small">Ejemplo: 40 + 26 + 30 = 96 in, sobrante 0. O 38 + 24 + 32 = 94 in, sobrante 2 in por cada pieza fuente.</div></div><div id="convSectionFields" style="display:none"><div class="form-grid"><label><span>Medida destino del catálogo</span><select id="convTargetFamily"><option value="">— Escribir otra medida —</option>${families.map(f=>`<option value="${f}">${f.replace('x','×')}</option>`).join('')}</select></label><label><span>Destino lado A</span><input id="convTargetA" type="number" min="0.125" step="0.125" value="1"></label><label><span>Destino lado B</span><input id="convTargetB" type="number" min="0.125" step="0.125" value="4"></label></div><div class="small">Aquí tú decides el rendimiento. Ejemplo: 2×4 → 0.5×4 = 3 piezas. El sistema agrega solo esas 3 y no registra el resto como desperdicio.</div></div><div id="convPreview" class="notification info"></div><div class="dialog-actions"><button class="btn" data-action="convertWood">Guardar operación</button></div></div>${wasteHistoryHtml()}`}
function renderProduccion(){const rows=state.orders.filter(o=>['waiting_material','cutting','material_ready'].includes(o.stage));return `<div class="toolbar"><button class="btn secondary" data-go="ordenes">Ir a Órdenes</button><input id="productionSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Etapa</th><th>Piezas requeridas / inventario</th><th>Acción</th></tr></thead><tbody>${rows.map(o=>{const status=pieceAvailability({products:orderProducts(o)}),ready=status.every(r=>r.ready),action=o.stage==='waiting_material'?(ready?`<button class="btn" data-cut-start="${o.id}">Reservar piezas listas</button>`:`<span class="small">Pendiente: faltan piezas</span>`):o.stage==='cutting'?`<button class="btn" data-cut-ready="${o.id}">Confirmar piezas listas</button>`:`<span class="small">Esperando fabricación</span>`,search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();return `<tr data-production-row data-search="${search.replace(/"/g,'&quot;')}"><td><b>#${o.id}</b>${o.clientOrder?`<div class="small">Cliente: ${o.clientOrder}</div>`:''}${orderRequirementHtml(o)}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td>${orderMaterialSummary(o)}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="7">No hay órdenes en esta etapa.</td></tr>'}</tbody></table></div><div class="section card"><b>Producción / Corte</b><p class="small">Las órdenes QC o HT muestran la alerta desde corte para que el material se procese con el nivel de cuidado requerido.</p></div>`}
function renderFabricacion(){const rows=state.orders.filter(o=>['material_ready','building'].includes(o.stage));return `<div class="grid metrics">${metric('Material listo',rows.filter(o=>o.stage==='material_ready').length,'Puede recogerlo el armador')}${metric('En fabricación',rows.filter(o=>o.stage==='building').length,'Trabajo activo')}${metric('Listas para carga',state.orders.filter(o=>o.stage==='ready_load').length,'Ya fabricadas')}${metric('Avisos',state.notifications.length,'Eventos recientes')}</div><div class="section table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows.map(o=>`<tr><td><b>#${o.id}</b>${orderRequirementHtml(o)}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td>${o.stage==='material_ready'?`<button class="btn" data-build-start="${o.id}">Iniciar fabricación</button>`:`<button class="btn" data-build-ready="${o.id}">Terminar y liberar</button>`}</td></tr>`).join('')||'<tr><td colspan="6">No hay órdenes en fabricación.</td></tr>'}</tbody></table></div><div class="section notification ok"><b>Aviso automático:</b> las marcas QC y HT siguen visibles durante fabricación; QC no bloquea el flujo si nadie registra la inspección.</div>`}
let palletInventoryView='new';
function palletCategoryLabel(c){return ({dismantle:'Para desarme',repair:'Para reparar',repaired:'Reparados listos'})[c]||c}
function palletInventoryRows(category){return (state.palletInventory||[]).filter(x=>x.category===category&&Number(x.qty)>0)}
function addPalletInventory(size,qty,category,sourceTrailer=''){size=String(size||'Sin medida').trim()||'Sin medida';qty=Math.max(0,Math.floor(Number(qty)||0));if(!qty)return;let x=(state.palletInventory||[]).find(v=>v.category===category&&String(v.size).toLowerCase()===size.toLowerCase());if(!x){x={id:'PI-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),size,qty:0,category,sourceTrailer};state.palletInventory.push(x)}x.qty+=qty}
function renderTerminados(){const total=state.finished.reduce((s,x)=>s+x.qty,0),res=state.finished.reduce((s,x)=>s+x.reserved,0),cat=palletInventoryView;const tabs=`<div class="toolbar pallet-inventory-tabs"><button class="btn ${cat==='new'?'':'secondary'}" data-pallet-tab="new">Nuevos</button><button class="btn ${cat==='dismantle'?'':'secondary'}" data-pallet-tab="dismantle">Para desarme</button><button class="btn ${cat==='repair'?'':'secondary'}" data-pallet-tab="repair">Para reparar</button><button class="btn ${cat==='repaired'?'':'secondary'}" data-pallet-tab="repaired">Reparados listos</button></div>`;if(cat==='new')return `${tabs}<div class="grid metrics">${metric('Fabricados',total,'Inventario nuevo actual')}${metric('Reservados',res,'Asignados a órdenes')}${metric('Disponibles',total-res,'Sin reservar')}${metric('Listos para carga',state.orders.filter(o=>o.stage==='ready_load').reduce((s,o)=>s+o.qty,0),'Pallets liberados')}</div><div class="section table-wrap"><table><thead><tr><th>SKU</th><th>Existencia</th><th>Reservado</th><th>Disponible</th></tr></thead><tbody>${state.finished.map(x=>`<tr><td><b>${x.sku}</b></td><td>${x.qty}</td><td>${x.reserved}</td><td>${x.qty-x.reserved}</td></tr>`).join('')||'<tr><td colspan="4">Sin pallets nuevos.</td></tr>'}</tbody></table></div>`;const rows=palletInventoryRows(cat);return `${tabs}<div class="grid metrics">${metric(palletCategoryLabel(cat),rows.reduce((a,x)=>a+Number(x.qty||0),0),'Pallets en esta categoría')}${metric('Medidas',rows.length,'Lotes separados por medida')}${metric('Origen','Reciclado','No se mezcla con pallets nuevos')}${metric('Estado',cat==='repaired'?'Listo':'Pendiente',cat==='dismantle'?'Pendiente de desarme':cat==='repair'?'Pendiente de reparación':'Disponible')}</div><div class="section table-wrap"><table><thead><tr><th>Medida</th><th>Cantidad</th><th>Categoría</th><th>Tráiler origen</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${x.size}</b></td><td>${x.qty}</td><td>${palletCategoryLabel(x.category)}</td><td>${x.sourceTrailer||'—'}</td></tr>`).join('')||'<tr><td colspan="4">Sin pallets en esta categoría.</td></tr>'}</tbody></table></div>`}

function shipPill(o){if(o.shipping==='pickup')return pill('Recogida del cliente','blue');if(o.stage==='transit')return pill('En tránsito','pink');return pill('Envío de fábrica','yellow')}
function renderCarga(){const rows=state.orders.filter(o=>o.stage!=='completed');return `<div class="toolbar"><button class="btn secondary" id="openLoadMaster">Abrir LoadMaster AI</button><input id="loadSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"><select><option>Todos</option><option>Envío de fábrica</option><option>Recogida del cliente</option><option>En tránsito</option></select></div><div class="grid two-col"><div><h2 style="font-size:16px">Pedidos y planificación de carga</h2>${rows.map(o=>{const ready=['ready_load','loading','transit'].includes(o.stage),search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();let action='';if(o.stage==='transit')action=`<button class="btn" data-transit-done="${o.id}">Marcar entregado</button>`;else if(ready)action=`<button class="btn" data-load-order="${o.id}">${o.stage==='loading'?'Continuar carga':(o.shipping==='pickup'?'Iniciar recogida':'Optimizar / iniciar carga')}</button>`;else action=`<button class="btn secondary" data-plan-load="${o.id}">Planear en LoadMaster</button><div class="small" style="margin-top:6px">Aún no se puede despachar: ${stageLabel(o.stage)}.</div>`;return `<div class="card order-card" data-load-card data-search="${search.replace(/"/g,'&quot;')}"><div class="order-card-top"><div>${shipPill(o)}<h3 style="margin:9px 0 3px">${o.customer}</h3><div class="small">Orden interna #${o.id}${o.clientOrder?` · Orden cliente ${o.clientOrder}`:''}</div><div class="small">${o.qty} pallets · ${o.product}</div>${orderRequirementHtml(o)}${o.trailerReturn&&o.trailerReturn!=='unknown'?`<div class="notification info" style="margin-top:8px"><b>Retorno de tráiler:</b> ${trailerReturnLabel(o.trailerReturn)}${o.trailerReturnNote?` · ${o.trailerReturnNote}`:''}</div>`:''}${progressFor(o.stage)}</div><div style="text-align:right"><div class="small">Estado</div><b>${stageLabel(o.stage)}</b><div style="height:8px"></div>${action}</div></div></div>`}).join('')||'<div class="empty-state">No hay pedidos.</div>'}</div><aside><div class="card"><h2 style="font-size:16px;margin-top:0">Planificación anticipada</h2><p class="small">Las preferencias del cliente viajan con la orden: QC, HT y retorno del tráiler aparecen aquí sin volver a capturarlas.</p></div><div class="card" style="margin-top:12px"><h2 style="font-size:16px;margin-top:0">Colores de despacho</h2><div>${pill('Envío de fábrica','yellow')}<div class="small" style="margin:5px 4px 12px">La fábrica pone tráiler y chofer.</div>${pill('Recogida del cliente','blue')}<div class="small" style="margin:5px 4px 12px">El cliente llega con su propio tráiler.</div>${pill('En tránsito','pink')}<div class="small" style="margin:5px 4px">El chofer de la fábrica va camino al cliente.</div></div></div></aside></div>`}
function localDayKey(value=new Date()){const d=value instanceof Date?value:new Date(value);if(Number.isNaN(d.getTime()))return '';const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function activeWorkers(){return (state.workers||[]).filter(w=>w&&w.active!==false&&String(w.name||'').trim())}
function workerName(id){return (state.workers||[]).find(w=>w.id===id)?.name||'Sin trabajador'}
function todayProductionEntries(){const key=localDayKey();return (state.productionLog||[]).filter(x=>x&&localDayKey(x.createdAt)===key)}
function dailyCutSummary(){const map=new Map();for(const e of todayProductionEntries().filter(x=>x.type==='length-cut'))for(const out of e.outputs||[]){const k=`${out.family}|${out.lengthIn}|${e.grade}`;const cur=map.get(k)||{family:out.family,lengthIn:Number(out.lengthIn)||0,grade:Number(e.grade)||0,qty:0};cur.qty+=Number(out.qty)||0;map.set(k,cur)}return [...map.values()].sort((a,b)=>a.family.localeCompare(b.family)||a.lengthIn-b.lengthIn||a.grade-b.grade)}
function workerDailySummary(){const map=new Map();for(const e of todayProductionEntries().filter(x=>x.type==='length-cut')){const id=e.workerId||'',cur=map.get(id)||{id,name:workerName(id),qty:0,jobs:0};cur.jobs+=1;cur.qty+=(e.outputs||[]).reduce((a,b)=>a+(Number(b.qty)||0),0);map.set(id,cur)}return [...map.values()].sort((a,b)=>b.qty-a.qty)}
function todayDismantleEntries(){const key=localDayKey();return (state.dismantleLog||[]).filter(e=>localDayKey(e.createdAt)===key)}
function renderResumen(){const rows=dailyCutSummary(),entries=todayProductionEntries().filter(x=>x.type==='length-cut'||x.type==='range-process').slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),dismantles=todayDismantleEntries().slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),fabs=(state.fabricationLog||[]).filter(x=>localDayKey(x.createdAt)===localDayKey()).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const total=rows.reduce((a,b)=>a+b.qty,0),activeToday=new Set([...entries,...dismantles,...fabs].map(e=>e.workerId).filter(Boolean));return `<div class="grid metrics">${metric('Piezas cortadas hoy',total,'Total de piezas terminadas')}${metric('Medidas diferentes',rows.length,'Cortes registrados hoy')}${metric('Trabajadores activos hoy',activeToday.size,'Con al menos una acción hoy')}${metric('Pallets desarmados hoy',dismantles.reduce((a,e)=>a+Number(e.palletQty||0),0),'Reciclaje registrado hoy')}</div><div class="section card"><div class="section-head"><div><h2>Trabajadores</h2><p>Activo si realizó al menos un corte, desarme o fabricación hoy; inactivo si todavía no ha realizado ninguna acción.</p></div><button class="btn" data-action="addWorker">+ Agregar trabajador</button></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Estado hoy</th></tr></thead><tbody>${(state.workers||[]).map(w=>`<tr><td><b>${w.name}</b></td><td>${activeToday.has(w.id)?pill('Activo','green'):pill('Inactivo','yellow')}</td></tr>`).join('')||'<tr><td colspan="2">No hay trabajadores. Agrega el primero.</td></tr>'}</tbody></table></div></div><div class="section"><div class="section-head"><div><h2>Fabricación de pallets hoy</h2><p>Costo de la hecha, material utilizado y costo total de fabricación.</p></div></div><div class="table-wrap"><table><thead><tr><th>Hora</th><th>Orden</th><th>Trabajador</th><th>Pallets</th><th>Fabricación</th><th>Material</th><th>Total</th></tr></thead><tbody>${fabs.map(e=>`<tr><td>${new Date(e.createdAt).toLocaleTimeString('es-US',{hour:'numeric',minute:'2-digit'})}</td><td><b>#${e.orderId}</b></td><td>${workerName(e.workerId)}</td><td>${e.qty}</td><td>${money(e.laborCost)}</td><td>${money(e.materialCost)}</td><td><b>${money(e.totalCost)}</b></td></tr>`).join('')||'<tr><td colspan="7">Sin pallets terminados hoy.</td></tr>'}</tbody></table></div></div><div class="section"><div class="section-head"><div><h2>Detalle de cortes de hoy</h2><p>Historial del día con trabajador, patrón realizado y desperdicio.</p></div></div><div class="table-wrap"><table><thead><tr><th>Hora</th><th>Trabajador</th><th>Fuente</th><th>Resultado</th><th>Desperdicio</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.createdAt).toLocaleTimeString('es-US',{hour:'numeric',minute:'2-digit'})}</td><td><b>${workerName(e.workerId)}</b></td><td>${e.sourceQty} × ${e.sourceSize}</td><td>${(e.outputs||[]).map(o=>`${o.qty} × ${o.family.replace('x','×')}×${o.lengthIn}`).join(', ')}</td><td>${Number(e.wasteTotalIn||0)} in</td></tr>`).join('')||'<tr><td colspan="5">Sin cortes registrados hoy.</td></tr>'}</tbody></table></div></div><div class="section"><div class="section-head"><div><h2>Desarme reciclado de hoy</h2><p>Quién desarmó pallets y qué material útil se recuperó.</p></div></div><div class="table-wrap"><table><thead><tr><th>Hora</th><th>Trabajador</th><th>Pallets</th><th>Referencia</th><th>Material recuperado</th></tr></thead><tbody>${dismantles.map(e=>`<tr><td>${new Date(e.createdAt).toLocaleTimeString('es-US',{hour:'numeric',minute:'2-digit'})}</td><td><b>${workerName(e.workerId)}</b></td><td>${e.palletQty}</td><td>${e.palletSize||'—'}</td><td>${(e.outputs||[]).map(o=>`${o.qty} × ${o.label}`).join(', ')}</td></tr>`).join('')||'<tr><td colspan="5">Sin desarme reciclado registrado hoy.</td></tr>'}</tbody></table></div></div>`}
function trailerStatusLabel(t){return t.status==='unloaded'?pill('Descargado','green'):pill('Pendiente de descarga','yellow')}
function todayUnloadedTrailers(){const key=localDayKey();return (state.inboundTrailers||[]).filter(t=>t.status==='unloaded'&&localDayKey(t.unloadedAt)===key)}
function renderTrailers(){const all=(state.inboundTrailers||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),pending=all.filter(t=>t.status!=='unloaded'),doneToday=todayUnloadedTrailers();return `<div class="grid metrics">${metric('Pendientes',pending.length,'Tráilers que todavía esperan descarga')}<button class="metric metric-button" data-action="todayUnloads" style="text-align:left;border:0;cursor:pointer"><div class="label">Descargados hoy</div><div class="value">${doneToday.length}</div><div class="hint">Toca para ver cuáles se descargaron</div></button></div><div class="toolbar"><button class="btn" data-action="newInboundTrailer">+ Registrar tráiler pendiente</button></div><div class="section table-wrap"><table><thead><tr><th>Tráiler</th><th>Proveedor / referencia</th><th>Fecha registro</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${all.map(t=>`<tr><td><b>${t.trailerNo||t.id}</b></td><td>${t.vendor||'—'}<div class="small">${t.notes||''}</div></td><td>${new Date(t.createdAt).toLocaleString('es-US')}</td><td>${trailerStatusLabel(t)}</td><td>${t.status==='unloaded'?`<button class="btn secondary" data-trailer-detail="${t.id}">Ver descarga</button>`:`<button class="btn" data-unload-trailer="${t.id}">Firmar descarga</button>`}</td></tr>`).join('')||'<tr><td colspan="5">No hay tráilers registrados.</td></tr>'}</tbody></table></div><div class="section notification info"><b>Importante:</b> registrar un tráiler pendiente no suma pallets al inventario. El inventario cambia únicamente al confirmar y firmar la descarga.</div>`}
function newInboundTrailerDialog(){openDialog('Registrar tráiler pendiente','Todavía no modifica ningún inventario',`<div class="form-grid"><label><span>Número / identificación del tráiler</span><input id="itTrailerNo" placeholder="Ej. TR-204"></label><label><span>Proveedor / referencia</span><input id="itVendor" placeholder="Ej. Compra reciclado"></label><label><span>Cantidad estimada (opcional)</span><input id="itExpected" type="number" min="0" value="0" placeholder="Se confirma al descargar"></label><label><span>Notas</span><input id="itNotes" placeholder="Opcional"></label></div><div class="dialog-actions"><button class="btn secondary" id="itCancel">Cancelar</button><button class="btn" id="itSave">Guardar pendiente</button></div>`);document.getElementById('itCancel').onclick=closeDialog;document.getElementById('itSave').onclick=()=>{const trailerNo=String(document.getElementById('itTrailerNo').value||'').trim();if(!trailerNo){toast('Escribe una identificación del tráiler.');return}state.inboundTrailers.push({id:'TR-'+Date.now(),trailerNo,vendor:String(document.getElementById('itVendor').value||'').trim(),expectedQty:Math.max(0,Math.floor(Number(document.getElementById('itExpected').value)||0)),notes:String(document.getElementById('itNotes').value||'').trim(),createdAt:new Date().toISOString(),status:'pending'});save();closeDialog();toast('Tráiler pendiente registrado. Aún no se agregó nada al inventario.');render()}}
function unloadDraftFormHtml(){return `<div class="card"><div class="form-grid"><label><span>Medida del pallet</span><input id="unloadDraftSize" placeholder="Ej. 48×40; para scrap puede quedar vacío"></label><label><span>Cantidad real</span><input id="unloadDraftQty" type="number" min="1" value="1"></label><label><span>Destino</span><select id="unloadDraftPurpose"><option value="dismantle">Para desarme / scrap</option><option value="repair">Para reparar</option></select></label></div><div class="dialog-actions"><button class="btn secondary" id="addUnloadLot">+ Agregar lote a la descarga</button></div></div>`}
function unloadLotsListHtml(lots){const total=lots.reduce((a,l)=>a+Number(l.qty||0),0);return `<div class="section"><div class="section-head"><div><h3>Lotes agregados</h3><p>${lots.length} lote(s) · ${total} pallets acumulados</p></div></div><div class="table-wrap"><table><thead><tr><th>Medida</th><th>Cantidad</th><th>Destino</th><th></th></tr></thead><tbody>${lots.map((l,i)=>`<tr><td><b>${l.size||'Scrap / sin medida'}</b></td><td>${l.qty}</td><td>${trailerPurposeLabel(l.purpose)}</td><td><button class="btn secondary" data-edit-unload-lot="${i}">Editar</button> <button class="btn secondary" data-remove-unload-lot="${i}">Eliminar</button></td></tr>`).join('')||'<tr><td colspan="4">Todavía no has agregado lotes.</td></tr>'}</tbody></table></div></div>`}
function unloadTrailerDialog(id){const t=(state.inboundTrailers||[]).find(x=>x.id===id);if(!t)return;const draftLots=[];let editing=-1,signatureDraft='',noteDraft='';const draw=()=>{openDialog('Firmar descarga',`Tráiler ${t.trailerNo||t.id} · registra cada medida como un lote separado`,`<div class="notification info">Agregar lote solo lo coloca en esta lista. Nada entra al inventario hasta confirmar la descarga completa.</div>${unloadDraftFormHtml()}<div id="unloadLotList">${unloadLotsListHtml(draftLots)}</div><div class="form-grid section"><label><span>Firma / nombre de quien recibe</span><input id="unloadSignature" value="${signatureDraft}" placeholder="Nombre completo"></label><label><span>Nota de recepción</span><input id="unloadNote" value="${noteDraft}" placeholder="Opcional"></label></div><div class="dialog-actions"><button class="btn secondary" id="unloadCancel">Cancelar</button><button class="btn" id="unloadSave">Firmar descarga · ${draftLots.reduce((a,l)=>a+Number(l.qty||0),0)} pallets</button></div>`);const size=document.getElementById('unloadDraftSize'),qty=document.getElementById('unloadDraftQty'),purpose=document.getElementById('unloadDraftPurpose');document.getElementById('unloadCancel').onclick=closeDialog;document.getElementById('addUnloadLot').onclick=()=>{const q=Math.max(0,Math.floor(Number(qty.value)||0)),pur=purpose.value||'dismantle',raw=String(size.value||'').trim(),finalSize=raw||(pur==='dismantle'?'Scrap / sin medida':'');if(!q||!finalSize){toast('Escribe cantidad y medida; para desarme la medida puede quedar vacía.');return}signatureDraft=String(document.getElementById('unloadSignature')?.value||'');noteDraft=String(document.getElementById('unloadNote')?.value||'');const lot={size:finalSize,qty:q,purpose:pur};if(editing>=0){draftLots[editing]=lot;editing=-1}else draftLots.push(lot);draw()};document.querySelectorAll('[data-remove-unload-lot]').forEach(b=>b.onclick=()=>{draftLots.splice(Number(b.dataset.removeUnloadLot),1);draw()});document.querySelectorAll('[data-edit-unload-lot]').forEach(b=>b.onclick=()=>{editing=Number(b.dataset.editUnloadLot);const l=draftLots[editing];size.value=l.size==='Scrap / sin medida'?'':l.size;qty.value=l.qty;purpose.value=l.purpose;document.getElementById('addUnloadLot').textContent='Guardar cambio del lote'});document.getElementById('unloadSave').onclick=()=>{const signature=String(document.getElementById('unloadSignature').value||'').trim();if(!signature){toast('Escribe quién firma la recepción.');return}if(!draftLots.length){toast('Agrega al menos un lote antes de firmar la descarga.');return}for(const l of draftLots)addPalletInventory(l.size,l.qty,l.purpose,t.trailerNo||t.id);t.status='unloaded';t.unloadedAt=new Date().toISOString();t.signature=signature;t.unloadNote=String(document.getElementById('unloadNote').value||'').trim();t.lots=clone(draftLots);save();closeDialog();toast('Descarga firmada. Cada lote fue enviado a su inventario correspondiente.');render()}};draw()}
function trailerPurposeLabel(p){return p==='repair'?'Para reparar':'Para desarme / scrap'}
function trailerDetailHtml(t){const lots=Array.isArray(t?.lots)?t.lots:[];return `<div class="grid two-col"><div class="card"><b>Proveedor / referencia</b><div>${t.vendor||'—'}</div></div><div class="card"><b>Tráiler</b><div>${t.trailerNo||t.id}</div></div><div class="card"><b>Registrado</b><div>${new Date(t.createdAt).toLocaleString('es-US')}</div></div><div class="card"><b>Descargado</b><div>${t.unloadedAt?new Date(t.unloadedAt).toLocaleString('es-US'):'—'}</div></div><div class="card"><b>Recibió / firmó</b><div>${t.signature||'—'}</div></div><div class="card"><b>Nota</b><div>${t.unloadNote||t.notes||'—'}</div></div></div><div class="section table-wrap"><table><thead><tr><th>Medida</th><th>Cantidad</th><th>Clasificación</th></tr></thead><tbody>${lots.map(l=>`<tr><td><b>${l.size||'Scrap / sin medida'}</b></td><td>${l.qty}</td><td>${trailerPurposeLabel(l.purpose)}</td></tr>`).join('')||'<tr><td colspan="3">Sin detalle de lotes.</td></tr>'}</tbody></table></div>`}
function openTrailerDetail(id){const t=(state.inboundTrailers||[]).find(x=>x.id===id);if(!t)return;openDialog('Detalle de descarga',`Tráiler ${t.trailerNo||t.id}`,trailerDetailHtml(t))}
function openTodayUnloads(){const rows=todayUnloadedTrailers().slice().sort((a,b)=>new Date(b.unloadedAt)-new Date(a.unloadedAt));openDialog('Descargados hoy',`${rows.length} tráiler(es) descargados hoy`,`<div class="table-wrap"><table><thead><tr><th>Tráiler</th><th>Proveedor</th><th>Hora</th><th>Recibió</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${t.trailerNo||t.id}</b></td><td>${t.vendor||'—'}</td><td>${new Date(t.unloadedAt).toLocaleTimeString('es-US',{hour:'numeric',minute:'2-digit'})}</td><td>${t.signature||'—'}</td><td><button class="btn secondary" data-dialog-trailer-detail="${t.id}">Ver detalle</button></td></tr>`).join('')||'<tr><td colspan="5">Todavía no se ha descargado ningún tráiler hoy.</td></tr>'}</tbody></table></div>`);document.querySelectorAll('[data-dialog-trailer-detail]').forEach(b=>b.onclick=()=>openTrailerDetail(b.dataset.dialogTrailerDetail))}
function recoveredRangeLabel(family,min,max,way=''){const wayLabel=way?` · ${String(way).toUpperCase()}`:'';return `${canonicalBoardFamily(family).replace('x','×')} × ${min}–${max} in${wayLabel} · reciclado sin medida final`}
function renderDesarme(){const entries=(state.dismantleLog||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const rowHtml=`<div class="card" data-dm-row><div class="form-grid"><label><span>Familia</span><input data-dm-family value="1x4"></label><label><span>Aplicación</span><select data-dm-way><option value="">Tabla / pieza general</option><option value="2-way">Runner 2-Way</option><option value="4-way">Runner 4-Way</option></select></label><label><span>Tipo</span><select data-dm-type><option value="exact">Medida exacta</option><option value="20-50">Rango 20–50 in</option><option value="50-80">Rango 50–80 in</option><option value="50-120">Rango 50–120 in</option></select></label><label><span>Largo exacto (in)</span><input data-dm-length type="number" min="1" value="40"></label><label><span>Cantidad recuperada</span><input data-dm-qty type="number" min="1" value="1"></label><div class="toolbar" style="align-items:end"><button class="btn secondary" data-remove-dm-row>Eliminar</button></div></div></div>`;return `<div class="grid metrics">${metric('Pallets desarmados',entries.reduce((a,e)=>a+Number(e.palletQty||0),0),'Histórico registrado')}${metric('Operaciones',entries.length,'Registros de desarme')}${metric('Hoy',todayDismantleEntries().reduce((a,e)=>a+Number(e.palletQty||0),0),'Pallets desarmados hoy')}${metric('Reciclado','Separado','Siempre entra al inventario como reciclado')}</div><div class="section card"><div class="section-head"><div><h2>Registrar desarme de pallets reciclados</h2><p>Indica quién desarmó los pallets y qué piezas útiles se recuperaron.</p></div></div><div class="form-grid"><label><span>Lote de pallets para desarme</span><select id="dmSourcePallet"><option value="">— Registro manual / sin lote —</option>${palletInventoryRows('dismantle').map(x=>`<option value="${x.id}">${x.size} · ${x.qty} disponibles</option>`).join('')}</select></label><label><span>Trabajador</span><select id="dmWorker"><option value="">— Seleccionar —</option>${activeWorkers().map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select></label><label><span>Pallets desarmados</span><input id="dmPalletQty" type="number" min="1" value="1"></label><label><span>Medida / referencia del pallet</span><input id="dmPalletSize" placeholder="Ej. 48×40"></label><div class="toolbar" style="align-items:end"><button class="btn secondary" data-action="addWorker">+ Agregar trabajador</button></div></div><div class="section-head section"><div><h2>Material recuperado</h2><p>Agrega piezas exactas o rangos de largo sin definir. Los runners reciclados pueden distinguirse como 2-Way o 4-Way.</p></div><button class="btn secondary" data-add-recovered>+ Agregar pieza</button></div><div id="dmRows">${rowHtml}</div><div class="notification info section"><b>Sin largo definido:</b> 20–50, 50–80 y 50–120 se procesan después desde Conversión. Al no conocerse el largo real, esa conversión no registra desperdicio.</div><div class="dialog-actions"><button class="btn" data-action="saveDismantle">Guardar desarme y sumar al inventario</button></div></div><div class="section"><div class="section-head"><div><h2>Historial de desarme</h2><p>Pallets desarmados y material recuperado.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Trabajador</th><th>Pallets</th><th>Referencia</th><th>Material recuperado</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.createdAt).toLocaleString('es-US')}</td><td>${workerName(e.workerId)}</td><td><b>${e.palletQty}</b></td><td>${e.palletSize||'—'}</td><td>${(e.outputs||[]).map(o=>`${o.qty} × ${o.label}`).join(', ')}</td></tr>`).join('')||'<tr><td colspan="5">Sin registros todavía.</td></tr>'}</tbody></table></div></div>`}
function addDismantleRow(){const box=document.getElementById('dmRows');if(!box)return;const d=document.createElement('div');d.className='card';d.dataset.dmRow='';d.innerHTML=`<div class="form-grid"><label><span>Familia</span><input data-dm-family value="1x4"></label><label><span>Aplicación</span><select data-dm-way><option value="">Tabla / pieza general</option><option value="2-way">Runner 2-Way</option><option value="4-way">Runner 4-Way</option></select></label><label><span>Tipo</span><select data-dm-type><option value="exact">Medida exacta</option><option value="20-50">Rango 20–50 in</option><option value="50-80">Rango 50–80 in</option><option value="50-120">Rango 50–120 in</option></select></label><label><span>Largo exacto (in)</span><input data-dm-length type="number" min="1" value="40"></label><label><span>Cantidad recuperada</span><input data-dm-qty type="number" min="1" value="1"></label><div class="toolbar" style="align-items:end"><button class="btn secondary" data-remove-dm-row>Eliminar</button></div></div>`;box.appendChild(d);bindDismantleRows()}
function bindDismantleRows(){document.querySelectorAll('[data-remove-dm-row]').forEach(b=>b.onclick=()=>{const rows=document.querySelectorAll('[data-dm-row]');if(rows.length<=1){toast('Deja al menos una fila.');return}b.closest('[data-dm-row]')?.remove()});document.querySelectorAll('[data-dm-type]').forEach(sel=>{const sync=()=>{const row=sel.closest('[data-dm-row]'),inp=row?.querySelector('[data-dm-length]');if(inp)inp.disabled=sel.value!=='exact'};sel.onchange=sync;sync()})}
function findOrCreateRangePiece(family,min,max,way=''){const fam=canonicalBoardFamily(family),kind=String(way||'');let x=state.lumber.find(v=>v.category==='range'&&v.origin==='recycled'&&canonicalBoardFamily(v.family)===fam&&Number(v.minLengthIn)===Number(min)&&Number(v.maxLengthIn)===Number(max)&&String(v.way||'')===kind);if(!x){x={id:'RG-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),category:'range',family:fam,origin:'recycled',grade:0,way:kind,minLengthIn:Number(min),maxLengthIn:Number(max),qty:0,reserved:0,min:0,size:recoveredRangeLabel(fam,min,max,kind)};state.lumber.push(x)}return x}
function saveDismantle(){const sourcePalletId=document.getElementById('dmSourcePallet')?.value||'',sourcePallet=(state.palletInventory||[]).find(x=>x.id===sourcePalletId),workerId=document.getElementById('dmWorker')?.value||'',palletQty=Math.max(1,Math.floor(Number(document.getElementById('dmPalletQty')?.value)||1)),palletSize=String(document.getElementById('dmPalletSize')?.value||sourcePallet?.size||'').trim();if(sourcePallet&&palletQty>Number(sourcePallet.qty||0)){toast('No hay suficientes pallets en ese lote para desarmar.');return}if(!workerId){toast('Selecciona quién realizó el desarme.');return}const outputs=[];for(const row of document.querySelectorAll('[data-dm-row]')){const family=canonicalBoardFamily(row.querySelector('[data-dm-family]')?.value||'1x4'),type=row.querySelector('[data-dm-type]')?.value||'exact',way=row.querySelector('[data-dm-way]')?.value||'',qty=Math.max(0,Math.floor(Number(row.querySelector('[data-dm-qty]')?.value)||0));if(!qty)continue;if(type==='exact'){const len=Math.max(1,Number(row.querySelector('[data-dm-length]')?.value)||1),dst=findOrCreateFinishedPiece(family,2,len,'recycled',way);dst.qty+=qty;outputs.push({family,way,lengthIn:len,qty,label:`${family.replace('x','×')} × ${len} in${way?` · ${way.toUpperCase()}`:''} · reciclado`})}else{const [min,max]=type.split('-').map(Number),dst=findOrCreateRangePiece(family,min,max,way);dst.qty+=qty;outputs.push({family,way,minLengthIn:min,maxLengthIn:max,qty,label:recoveredRangeLabel(family,min,max,way)})}}if(!outputs.length){toast('Agrega al menos una pieza recuperada.');return}state.dismantleLog=Array.isArray(state.dismantleLog)?state.dismantleLog:[];if(sourcePallet)sourcePallet.qty-=palletQty;state.dismantleLog.push({id:'DM-'+Date.now(),createdAt:new Date().toISOString(),workerId,palletQty,palletSize,outputs});addNote(`Desarme reciclado: ${workerName(workerId)} desarmó ${palletQty} pallets y recuperó ${outputs.reduce((a,o)=>a+o.qty,0)} piezas.`);save();toast('Desarme guardado y material reciclado agregado al inventario.');render()}

function renderReportes(){const completed=state.history.length;return `<div class="grid metrics">${metric('Órdenes activas',state.orders.filter(o=>o.stage!=='completed').length,'Operación actual')}${metric('Pallets terminados',state.finished.reduce((s,x)=>s+x.qty,0),'Inventario')}${metric('Despachos históricos',completed,'En este demo')}${metric('Retención',state.settings.historyDays+' días','Configurable')}</div><div class="section grid two-col"><div class="card"><h2 style="font-size:16px;margin-top:0">Resumen por etapa</h2><div class="status-list">${['waiting_material','cutting','material_ready','building','ready_load','transit'].map(s=>`<div class="status-row"><span class="dot"></span><div>${stageLabel(s)}</div><b>${state.orders.filter(o=>o.stage===s).length}</b></div>`).join('')}</div></div><div class="card"><h2 style="font-size:16px;margin-top:0">Idea de producción sumario</h2><p class="small">Este módulo concentra la información de productividad sin obligar a crear un menú separado para cada reporte.</p></div></div>`}
function renderHistorial(){const type=historyView;const selector=`<div class="toolbar"><label class="small">Tipo de historial <select id="historyType"><option value="sales" ${type==='sales'?'selected':''}>Venta de pallets</option><option value="wood" ${type==='wood'?'selected':''}>Compra de madera</option><option value="unloads" ${type==='unloads'?'selected':''}>Descarga de tráilers</option></select></label><label class="small">Retención <select id="historyDays"><option value="30" ${state.settings.historyDays===30?'selected':''}>30 días</option><option value="60" ${state.settings.historyDays===60?'selected':''}>60 días</option><option value="90" ${state.settings.historyDays===90?'selected':''}>90 días</option></select></label></div>`;let body='';if(type==='wood'){const rows=(state.lumberPurchaseLog||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));body=`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Material</th><th>Origen</th><th>Cantidad</th><th>Precio/pieza</th><th>Total compra</th></tr></thead><tbody>${rows.map(h=>`<tr><td>${new Date(h.createdAt).toLocaleString('es-US')}</td><td><b>${h.size}</b></td><td>${h.origin==='recycled'?'Reciclado':'Nuevo'}${h.origin==='recycled'?'':` · #${h.grade}`}</td><td>${h.qty}</td><td>${money(h.unitPrice)}</td><td><b>${money(h.totalCost)}</b></td></tr>`).join('')||'<tr><td colspan="6">Aún no hay compras/recepciones de madera registradas.</td></tr>'}</tbody></table></div>`}else if(type==='unloads'){const rows=(state.inboundTrailers||[]).filter(t=>t.status==='unloaded').slice().sort((a,b)=>new Date(b.unloadedAt)-new Date(a.unloadedAt));body=`<div class="table-wrap"><table><thead><tr><th>Descarga</th><th>Tráiler</th><th>Proveedor</th><th>Recibió</th><th>Detalle</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${new Date(t.unloadedAt).toLocaleString('es-US')}</td><td><b>${t.trailerNo||t.id}</b></td><td>${t.vendor||'—'}</td><td>${t.signature||'—'}</td><td><button class="btn secondary" data-trailer-detail="${t.id}">Abrir</button></td></tr>`).join('')||'<tr><td colspan="5">Sin descargas registradas.</td></tr>'}</tbody></table></div>`}else{body=`<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Tipo</th><th>Completado</th><th>Resultado</th><th></th></tr></thead><tbody>${state.history.map(h=>`<tr><td>#${h.id}${h.clientOrder?`<div class="small">Cliente: ${h.clientOrder}</div>`:''}</td><td>${h.customer}</td><td>${h.shipping==='pickup'?'Recogida cliente':'Envío fábrica'}</td><td>${h.completed}</td><td>${money(h.profitTotal||0)} ganancia</td><td><button class="btn secondary" data-sale-history="${h.id}">Ver detalle</button></td></tr>`).join('')||'<tr><td colspan="6">Sin ventas completadas.</td></tr>'}</tbody></table></div>`}return `${selector}${body}<div class="section notification">El historial está separado por tipo para evitar mezclar compras, ventas y recepciones de tráilers.</div>`}
function openSaleHistoryDetail(id){const h=(state.history||[]).find(x=>String(x.id)===String(id));if(!h)return;const products=Array.isArray(h.products)?h.products:[];const rows=products.map(p=>{const qty=Number(p.qty)||0,price=Number(p.salePrice)||0,cost=Number(p.costSummary?.totalCost)||0,sales=qty*price,profit=sales-cost;return `<tr><td><b>${p.length}×${p.width}</b></td><td>${qty}</td><td>${money(price)}</td><td>${money(cost)}</td><td>${money(sales)}</td><td><b>${money(profit)}</b></td></tr>`}).join('');openDialog(`Venta · Orden #${h.id}`,`${h.customer} · ${h.completed||''}`,`<div class="table-wrap"><table><thead><tr><th>Medida</th><th>Cantidad</th><th>Venta/pallet</th><th>Costo total</th><th>Venta total</th><th>Ganancia</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Esta venta antigua no tiene desglose de costos guardado.</td></tr>'}</tbody></table></div><div class="grid metrics section">${metric('Costo de la orden',money(h.costTotal||0),'Material + fabricación')}${metric('Venta total',money(h.salesTotal||0),'Importe de pallets')}${metric('Ganancia total',money(h.profitTotal||0),'Venta menos costos')}</div>${(h.qcRequired||h.htRequired)?`<div class="notification info"><b>Requisitos:</b> ${h.qcRequired?`QC ${h.qcCompletedAt?'registrado':'requerido'}`:''}${h.qcRequired&&h.htRequired?' · ':''}${h.htRequired?'HT requerido':''}</div>`:''}<div class="notification info">${h.evidence||'Sin evidencia registrada'}</div>`)}
function renderConfiguracion(){const t=state.settings.theme||'system',customers=(state.customers||[]);return `<div class="grid two-col"><section class="card"><h2 style="margin-top:0;font-size:17px">Apariencia</h2><p class="small">El tema se aplica a toda Pallet Operations y se entrega también a LoadMaster AI.</p><label class="theme-setting"><span>Tema</span><select id="settingsTheme"><option value="light" ${t==='light'?'selected':''}>Claro</option><option value="dark" ${t==='dark'?'selected':''}>Oscuro</option><option value="system" ${t==='system'?'selected':''}>Automático (sistema)</option></select></label><div class="theme-preview-row"><div class="theme-swatch light-swatch">Claro</div><div class="theme-swatch dark-swatch">Oscuro</div></div></section><section class="card"><h2 style="margin-top:0;font-size:17px">Reglas visuales de pallets</h2><p class="small">2-Way Runner usa runners rectos. 4-Way Runner usa runners con muescas. Block se trata siempre como 4-Way. Crates muestran únicamente su pallet base; plywood ya puede registrarse en inventario y su optimizador se conectará después.</p></section></div><section class="card section"><div class="section-head"><div><h2>Preferencias por cliente</h2><p>Reglas que se cargan automáticamente al crear una orden y siempre se pueden cambiar para un pedido específico.</p></div><button class="btn" data-action="addCustomerPref">+ Agregar cliente</button></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>QC predeterminado</th><th>HT predeterminado</th><th>Retorno de tráiler</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr><td><b>${c.name}</b></td><td>${c.qcDefault?pill('Sí','yellow'):'No'}</td><td>${c.htDefault?pill('Sí','purple'):'No'}</td><td>${trailerReturnLabel(c.trailerReturn)}${c.trailerReturnNote?`<div class="small">${c.trailerReturnNote}</div>`:''}</td><td><button class="btn secondary" data-edit-customer-pref="${c.id}">Editar</button></td></tr>`).join('')||'<tr><td colspan="5">Aún no hay preferencias guardadas.</td></tr>'}</tbody></table></div></section><section class="card section"><h2 style="margin-top:0;font-size:17px">Usuarios y permisos · preparación</h2><p class="small">La versión actual sigue siendo de administrador. La fase multiusuario separará oficina, producción, montacarguista y chofer. Los precios, costos, ganancias y pago de fabricación se ocultarán a los roles no autorizados.</p></section>`}
function customerPreferenceDialog(id=''){const existing=(state.customers||[]).find(c=>c.id===id)||{name:'',qcDefault:false,htDefault:false,trailerReturn:'unknown',trailerReturnNote:''};openDialog(existing.id?'Editar preferencias':'Agregar cliente','Preferencias automáticas para futuras órdenes',`<div class="form-grid"><label><span>Cliente</span><input id="cpName" value="${existing.name||''}" ${existing.id?'readonly':''}></label><label><span>Retorno de tráiler</span><select id="cpReturn"><option value="unknown" ${existing.trailerReturn==='unknown'?'selected':''}>Sin regla definida</option><option value="same-day" ${existing.trailerReturn==='same-day'?'selected':''}>Regresa el mismo día</option><option value="multi-day" ${existing.trailerReturn==='multi-day'?'selected':''}>Se queda varios días</option></select></label><label class="wide"><span>Nota de retorno / logística</span><input id="cpReturnNote" value="${existing.trailerReturnNote||''}" placeholder="Ej. normalmente regresa en 3–5 días"></label><label class="check-row"><input id="cpQc" type="checkbox" ${existing.qcDefault?'checked':''}><span>Control de calidad predeterminado</span></label><label class="check-row"><input id="cpHt" type="checkbox" ${existing.htDefault?'checked':''}><span>Heat Treatment (HT) predeterminado</span></label></div><div class="dialog-actions"><button class="btn secondary" id="cpCancel">Cancelar</button><button class="btn" id="cpSave">Guardar</button></div>`);document.getElementById('cpCancel').onclick=closeDialog;document.getElementById('cpSave').onclick=()=>{const name=String(document.getElementById('cpName').value||'').trim();if(!name){toast('Escribe el cliente.');return}const c=existing.id?existing:upsertCustomer(name);c.qcDefault=Boolean(document.getElementById('cpQc').checked);c.htDefault=Boolean(document.getElementById('cpHt').checked);c.trailerReturn=document.getElementById('cpReturn').value;c.trailerReturnNote=String(document.getElementById('cpReturnNote').value||'').trim();save();closeDialog();toast('Preferencias del cliente guardadas.');render()}}
function navigate(v){currentView=v;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.getElementById('sidebar').classList.remove('open');render()}
function openDialog(title,subtitle,body){el.dialog.classList.remove('fullscreen');el.dialogTitle.textContent=title;el.dialogSubtitle.textContent=subtitle||'';el.dialogBody.innerHTML=body;if(!el.dialog.open)el.dialog.showModal()}
function openFullDialog(title,subtitle,body){el.dialog.classList.add('fullscreen');el.dialogTitle.textContent=title;el.dialogSubtitle.textContent=subtitle||'';el.dialogBody.innerHTML=body;if(!el.dialog.open)el.dialog.showModal()}
function closeDialog(){el.dialog.close();el.dialog.classList.remove('fullscreen')}
function bindDynamic(){
  document.querySelectorAll('[data-ai-query]').forEach(b=>b.addEventListener('click',async()=>{await ensureAIAssistantLoaded();const input=document.querySelector('#aiAssistantMount textarea');if(input){input.value=b.dataset.aiQuery;input.focus()}}));
  document.querySelector('[data-ai-audit]')?.addEventListener('click',updateAIAuditSummary);
  document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>navigate(x.dataset.go));
  document.querySelectorAll('[data-cut-start]').forEach(x=>x.onclick=()=>startCut(x.dataset.cutStart));
  document.querySelectorAll('[data-cut-ready]').forEach(x=>x.onclick=()=>finishCut(x.dataset.cutReady));
  document.querySelectorAll('[data-build-start]').forEach(x=>x.onclick=()=>startBuild(x.dataset.buildStart));
  document.querySelectorAll('[data-build-ready]').forEach(x=>x.onclick=()=>finishBuildDialog(x.dataset.buildReady));
  document.querySelectorAll('[data-load-order]').forEach(x=>x.onclick=()=>openLoadOrder(x.dataset.loadOrder));
  document.querySelectorAll('[data-plan-load]').forEach(x=>x.onclick=()=>openLoadPreparation(x.dataset.planLoad));
  document.querySelectorAll('[data-order-spec]').forEach(x=>x.onclick=()=>openOrderSpecification(x.dataset.orderSpec));document.querySelectorAll('[data-qc-done]').forEach(x=>x.onclick=()=>markQualityCheck(x.dataset.qcDone));
  document.querySelectorAll('[data-transit-done]').forEach(x=>x.onclick=()=>completeDelivery(x.dataset.transitDone));
  document.getElementById('openLoadMaster')?.addEventListener('click',openLoadMaster);
  document.querySelector('[data-action="receiveWood"]')?.addEventListener('click',receiveWoodDialog);
  document.querySelector('[data-action="newInboundTrailer"]')?.addEventListener('click',newInboundTrailerDialog);document.querySelector('[data-action="todayUnloads"]')?.addEventListener('click',openTodayUnloads);document.querySelectorAll('[data-unload-trailer]').forEach(b=>b.addEventListener('click',()=>unloadTrailerDialog(b.dataset.unloadTrailer)));document.querySelectorAll('[data-trailer-detail]').forEach(b=>b.addEventListener('click',()=>openTrailerDetail(b.dataset.trailerDetail)));document.querySelectorAll('[data-sale-history]').forEach(b=>b.addEventListener('click',()=>openSaleHistoryDetail(b.dataset.saleHistory)));
  document.querySelectorAll('[data-pallet-tab]').forEach(b=>b.addEventListener('click',()=>{palletInventoryView=b.dataset.palletTab;render()}));
  document.querySelector('[data-action="addMaterial"]')?.addEventListener('click',addMaterialDialog);document.querySelector('[data-action="addSheetMaterial"]')?.addEventListener('click',addSheetMaterialDialog);
  document.querySelector('[data-add-recovered]')?.addEventListener('click',addDismantleRow);document.querySelector('[data-action="saveDismantle"]')?.addEventListener('click',saveDismantle);if(currentView==='desarme')bindDismantleRows();
  document.querySelector('[data-action="convertWood"]')?.addEventListener('click',convertWoodFromView);
  document.getElementById('convOperation')?.addEventListener('change',()=>{syncConversionOperationFields();updateConversionPreview()});document.getElementById('convSource')?.addEventListener('change',updateConversionPreview);document.getElementById('convQty')?.addEventListener('input',updateConversionPreview);document.getElementById('convYield')?.addEventListener('input',updateConversionPreview);document.getElementById('convTargetFamily')?.addEventListener('change',e=>{const d=parseFamilyDims(e.target.value);if(d){document.getElementById('convTargetA').value=d[0];document.getElementById('convTargetB').value=d[1]}updateConversionPreview()});document.getElementById('convTargetA')?.addEventListener('input',updateConversionPreview);document.getElementById('convTargetB')?.addEventListener('input',updateConversionPreview);document.querySelector('[data-add-cut]')?.addEventListener('click',addCutRow);document.querySelectorAll('[data-cut-row] input').forEach(x=>x.addEventListener('input',updateConversionPreview));document.querySelectorAll('[data-remove-cut]').forEach(x=>x.addEventListener('click',removeCutRow));if(currentView==='conversion'){syncConversionOperationFields();updateConversionPreview()}
  document.querySelector('[data-action="physicalCount"]')?.addEventListener('click',()=>toast('Prototipo: aquí se capturaría un conteo físico.'));
  document.querySelector('[data-action="newOrder"]')?.addEventListener('click',newOrderDialog);
  document.querySelector('[data-action="autoPlan"]')?.addEventListener('click',()=>toast('El optimizador de corte se aplicará después solo a las órdenes que selecciones.'));document.querySelector('[data-action="addWorker"]')?.addEventListener('click',addWorkerDialog);document.querySelectorAll('[data-toggle-worker]').forEach(x=>x.addEventListener('click',()=>{const w=(state.workers||[]).find(v=>v.id===x.dataset.toggleWorker);if(w){w.active=w.active===false;save();render()}}));
  document.querySelector('[data-action="addCustomerPref"]')?.addEventListener('click',()=>customerPreferenceDialog());document.querySelectorAll('[data-edit-customer-pref]').forEach(x=>x.addEventListener('click',()=>customerPreferenceDialog(x.dataset.editCustomerPref)));
  document.getElementById('historyType')?.addEventListener('change',e=>{historyView=e.target.value;render()});document.getElementById('historyDays')?.addEventListener('change',e=>{state.settings.historyDays=Number(e.target.value);save();toast('Retención actualizada a '+e.target.value+' días.')});document.getElementById('settingsTheme')?.addEventListener('change',e=>{setTheme(e.target.value);toast('Apariencia actualizada.')});
  document.getElementById('ordersSearch')?.addEventListener('input',e=>filterBySearch('[data-order-row]',e.target.value));
  document.getElementById('productionSearch')?.addEventListener('input',e=>filterBySearch('[data-production-row]',e.target.value));
  document.getElementById('loadSearch')?.addEventListener('input',e=>filterBySearch('[data-load-card]',e.target.value));
}
function filterBySearch(selector,value){const q=String(value||'').trim().toLowerCase();document.querySelectorAll(selector).forEach(el=>{el.style.display=!q||String(el.dataset.search||'').includes(q)?'':'none'})}
