function boardRowsHtml(side,rows,condition='new'){const families=boardCatalogFamilies(rows),hideQuality=false;return `<div class="board-editor" data-board-side="${side}"><div class="board-editor-head"><b>${side==='top'?'Tablas arriba':'Tablas abajo'}</b><button type="button" class="btn ghost" data-add-board="${side}">+ Agregar tipo de tabla</button></div>${rows.map((r,i)=>{const fam=boardFamilyOf(r),known=families.includes(fam);return `<div class="board-row board-row-v09" data-board-row="${side}-${i}"><label><span>Tabla</span><select data-board-family>${families.map(f=>`<option value="${f}" ${fam===f?'selected':''}>${f.replace('x','×')}</option>`).join('')}<option value="__custom__" ${known?'':'selected'}>+ Crear nueva medida…</option></select></label><label data-board-custom-wrap style="${known?'display:none':''}"><span>Nueva medida</span><input data-board-custom value="${known?'':fam.replace('x','×')}" placeholder="Ej. 1×5"></label><label><span>Largo de tabla (in)</span><input data-board-length type="number" min="1" value="${Number(r.length)||40}"></label><label><span>Cantidad por pallet</span><input data-board-qty type="number" min="0" value="${Number(r.qty)||0}"></label>${hideQuality?'':`<label><span>Calidad exacta</span><select data-board-grade>${palletQualityOptions(r.grade,condition)}</select></label>`}<button type="button" class="remove-board" data-remove-board="${side}-${i}" aria-label="Eliminar tipo">×</button></div>`}).join('')}<div class="deck-help small">Puedes elegir cualquier medida usada antes o existente en inventario. Si no existe, selecciona “Crear nueva medida”. El largo de la tabla es independiente del ancho general del pallet.${hideQuality?' En Combo solo se define medida y cantidad; la calidad se registrará al finalizar fabricación.':''}</div></div>`}
