function productGradeSummary(p){const grades=[];if(Number(p.runnerGrade))grades.push(Number(p.runnerGrade));for(const b of p.blocks||[])if(Number(b.grade))grades.push(Number(b.grade));for(const r of [...(p.topBoards||[]),...(p.bottomBoards||[])])if(Number(r.grade))grades.push(Number(r.grade));const u=[...new Set(grades)];return u.length===1?'#'+u[0]:(u.length?u.map(g=>'#'+g).join(' / '):'—')}
